const raw = $input.first().json.body || $input.first().json;
const kind = String(raw.kind || 'operations').toLowerCase();
const isMarketing = kind === 'marketing' || kind === 'social';

return [{
  json: {
    tenantId: raw.tenantId || 'eds-360',
    scope: 'department',
    key: isMarketing ? 'marketing' : 'operations',
    sourceLabel: raw.sourceLabel || `n8n-${kind}`,
    kpis: Array.isArray(raw.kpis) ? raw.kpis : [
      { label: 'Active Queue', value: String(raw.queueCount ?? 1), sub: `Stream: ${kind}`, accent: 'text-cyan-300' },
      { label: 'BoE / SOP / Post State', value: raw.state || 'Stamped', sub: 'Audit & review tracked', accent: 'text-emerald-300' },
      { label: 'HITL Gate', value: 'Required', sub: 'Human sign-off before send/post', accent: 'text-amber-300' },
      { label: 'Last Sync', value: new Date().toISOString().slice(11, 19) + 'Z', sub: 'Automated ingest', accent: 'text-indigo-300' }
    ],
    items: Array.isArray(raw.items) && raw.items.length > 0 ? raw.items : [
      {
        ref: raw.ref || `${kind.toUpperCase()}-${Date.now().toString().slice(-4)}`,
        owner: raw.owner || (isMarketing ? 'Marketing & Legal' : 'Ops & BoE Lead'),
        detail: raw.detail || `${kind} item staged for review (AU.L2-3.3.1)`,
        status: raw.itemStatus || 'pending_approval'
      }
    ]
  }
}];
